<div class="head"><h1><?= $p['id'] ?? 0 ? 'تعديل المنتج' : 'منتج جديد' ?></h1><?php if (!empty($p['slug'])): ?><a class="btn btn-ghost sm" target="_blank" href="<?= url('p/' . $p['slug']) ?>">عرض فالمتجر</a><?php endif; ?></div>
