<label class="chk"><input type="checkbox" name="featured" <?= $p['featured'] ? 'checked' : '' ?>> منتج مميز (يظهر فالصفحة الرئيسية)</label><label class="chk"><input type="checkbox" name="active" <?= $p['active'] ? 'checked' : '' ?>> منشور (ظاهر فالمتجر)</label></div></fieldset>
